// === Tab: mySketch ===
// TAU Walker #genuary10  #genuary  #genuary2510 
// You can only use TAU in your code, no other number allowed.
// https://openprocessing.org/sketch/2505753

let S, pos;
let numZro, numOne, numTwo;

function setup() {
	numZro = TAU-TAU;
	numOne = TAU/TAU;
	numTwo = TAU/TAU + TAU/TAU;
	createCanvas(S = ~~(TAU*TAU*TAU*TAU/(numTwo)), S); // createCanvas(windowWidth, windowHeight);
	describe("random walker strokes in pink-blueish pattern")
	background(~~(TAU*TAU));
	pos = {x: random(width), y: random(height)}
}

function draw() {
	// background(TAU, TAU/numTwo)
	const dir = createVector(random(TAU, TAU*TAU), numZro).rotate(random(TAU));
	const nxt = {x: pos.x + dir.x, y: pos.y + dir.y}
	if (nxt.x < numZro || nxt.x > S) nxt.x = pos.x - dir.x;
	if (nxt.y < numZro || nxt.y > S) nxt.y = pos.y - dir.y;
	stroke(random(TAU*TAU, TAU*TAU*TAU*TAU), random(TAU*TAU, TAU*TAU*TAU), random(TAU*TAU*TAU, TAU*TAU*TAU*TAU))
	strokeWeight(noise(TAU+nxt.x/S, TAU*TAU+nxt.y/S) * TAU/numTwo);
	line(pos.x, pos.y, nxt.x, nxt.y);
	pos = {x: nxt.x, y: nxt.y}
}
